-- Number Of Ask Orders
tmx_mx_solamulticast_hsvf_v1_11.number_of_ask_orders = {}

-- Size: Number Of Ask Orders
tmx_mx_solamulticast_hsvf_v1_11.number_of_ask_orders.size = 2

-- Display: Number Of Ask Orders
tmx_mx_solamulticast_hsvf_v1_11.number_of_ask_orders.display = function(value, buffer, offset, packet, parent)
  return "Number Of Ask Orders: "..string.format("%.0f", value)
end

-- Dissect: Number Of Ask Orders
tmx_mx_solamulticast_hsvf_v1_11.number_of_ask_orders.dissect = function(buffer, offset, packet, parent)
  local length = tmx_mx_solamulticast_hsvf_v1_11.number_of_ask_orders.size
  local range = buffer(offset, length)
  local text = range:string()
  local powers = { ["C"] = 2, ["D"] = 3, ["E"] = 4, ["F"] = 5, ["G"] = 6, ["H"] = 7, ["I"] = 8, ["J"] = 9 }
  local value = 0
  local power = 0

  for index = 1, #text do
    local character = text:sub(index, index)
    if powers[character] then
      power = powers[character]
    else
      value = value * 10 + (tonumber(character) or 0)
    end
  end

  value = value * (10 ^ power)

  local display = tmx_mx_solamulticast_hsvf_v1_11.number_of_ask_orders.display(value, buffer, offset, packet, parent)

  parent:add(omi_tmx_mx_solamulticast_hsvf_v1_11.fields.number_of_ask_orders, range, value, display)

  return offset + length, value
end

