    return tmx_mx_solamulticast_hsvf_v1_11.tick_price_negative_hundred_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Tick Price Negative Thousand Pair
  if tick_price_fraction_indicator == "D" then
    return tmx_mx_solamulticast_hsvf_v1_11.tick_price_negative_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Tick Price Negative Ten Thousand Pair
  if tick_price_fraction_indicator == "E" then
    return tmx_mx_solamulticast_hsvf_v1_11.tick_price_negative_ten_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Tick Price Negative Hundred Thousand Pair
