    return tmx_mx_solamulticast_hsvf_v1_11.tick_price_negative_hundred_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Tick Price Negative Million Pair
  if tick_price_fraction_indicator == "G" then
    return tmx_mx_solamulticast_hsvf_v1_11.tick_price_negative_million_pair.dissect(buffer, offset, packet, parent)
  end

  -- Dissect Tick Price Numeric Pair
  return tmx_mx_solamulticast_hsvf_v1_11.tick_price_numeric_pair.dissect(buffer, offset, packet, parent)
end

