-- Dissect: Min Price Fraction Pair
tmx_mx_solamulticast_hsvf_v1_11.min_price_fraction_pair.dissect = function(buffer, offset, packet, parent, min_price_fraction_indicator)
  -- Dissect Min Price Negative Whole Pair
  if min_price_fraction_indicator == "A" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_whole_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Min Price Negative Ten Pair
  if min_price_fraction_indicator == "B" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_ten_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Min Price Negative Hundred Pair
  if min_price_fraction_indicator == "C" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_hundred_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Min Price Negative Thousand Pair
  if min_price_fraction_indicator == "D" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Min Price Negative Ten Thousand Pair
  if min_price_fraction_indicator == "E" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_ten_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Min Price Negative Hundred Thousand Pair
  if min_price_fraction_indicator == "F" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_hundred_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Min Price Negative Million Pair
  if min_price_fraction_indicator == "G" then
    return tmx_mx_solamulticast_hsvf_v1_11.min_price_negative_million_pair.dissect(buffer, offset, packet, parent)
  end

  -- Dissect Min Price Numeric Pair
  return tmx_mx_solamulticast_hsvf_v1_11.min_price_numeric_pair.dissect(buffer, offset, packet, parent)
end

