-- Calculate size of: Tick Table Message
tmx_mx_solamulticast_hsvf_v1_11.tick_table_message.size = function(buffer, offset)
  local index = 0

  index = index + tmx_mx_solamulticast_hsvf_v1_11.exchange_id.size

  index = index + tmx_mx_solamulticast_hsvf_v1_11.tick_table_name.size

  index = index + tmx_mx_solamulticast_hsvf_v1_11.tick_table_short_name.size

  index = index + tmx_mx_solamulticast_hsvf_v1_11.number_of_entries.size

  -- Calculate field size from count
  local tick_entry_group_count = buffer(offset + index - 2, 2):string()
  for i = 1, tick_entry_group_count do
    index = index + tmx_mx_solamulticast_hsvf_v1_11.tick_entry_group.size(buffer, offset + index)
  end
  return index
end

