tmx_mx_solamulticast_hsvf_v1_11.tick_table_message.fields = function(buffer, offset, packet, parent)
  local index = offset

  -- Exchange Id: A
  index, exchange_id = tmx_mx_solamulticast_hsvf_v1_11.exchange_id.dissect(buffer, index, packet, parent)

  -- Tick Table Name: X
  index, tick_table_name = tmx_mx_solamulticast_hsvf_v1_11.tick_table_name.dissect(buffer, index, packet, parent)

  -- Tick Table Short Name: X
  index, tick_table_short_name = tmx_mx_solamulticast_hsvf_v1_11.tick_table_short_name.dissect(buffer, index, packet, parent)

  -- Number Of Entries: N
  index, number_of_entries = tmx_mx_solamulticast_hsvf_v1_11.number_of_entries.dissect(buffer, index, packet, parent)

  -- Repeating: Tick Entry Group
  for tick_entry_group_index = 1, number_of_entries do
    index, tick_entry_group = tmx_mx_solamulticast_hsvf_v1_11.tick_entry_group.dissect(buffer, index, packet, parent, tick_entry_group_index)
  end

  return index
end

