    return tmx_mx_solamulticast_hsvf_v1_11.high_price_negative_hundred_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect High Price Negative Million Pair
  if high_price_fraction_indicator == "G" then
    return tmx_mx_solamulticast_hsvf_v1_11.high_price_negative_million_pair.dissect(buffer, offset, packet, parent)
  end

  -- Dissect High Price Numeric Pair
  return tmx_mx_solamulticast_hsvf_v1_11.high_price_numeric_pair.dissect(buffer, offset, packet, parent)
end

