    return tmx_mx_solamulticast_hsvf_v1_11.external_price_at_source_negative_hundred_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect External Price At Source Negative Thousand Pair
  if external_price_fraction_indicator == "D" then
    return tmx_mx_solamulticast_hsvf_v1_11.external_price_at_source_negative_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect External Price At Source Negative Ten Thousand Pair
  if external_price_fraction_indicator == "E" then
    return tmx_mx_solamulticast_hsvf_v1_11.external_price_at_source_negative_ten_thousand_pair.dissect(buffer, offset, packet, parent)
