    return tmx_mx_solamulticast_hsvf_v1_11.external_price_at_source_negative_hundred_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect External Price At Source Negative Million Pair
  if external_price_fraction_indicator == "G" then
    return tmx_mx_solamulticast_hsvf_v1_11.external_price_at_source_negative_million_pair.dissect(buffer, offset, packet, parent)
  end

  -- Dissect External Price At Source Numeric Pair
  return tmx_mx_solamulticast_hsvf_v1_11.external_price_at_source_numeric_pair.dissect(buffer, offset, packet, parent)
end

