-- Dissect: Previous Settlement Fraction Pair
tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_fraction_pair.dissect = function(buffer, offset, packet, parent, previous_settlement_fraction_indicator)
  -- Dissect Previous Settlement Negative Whole Pair
  if previous_settlement_fraction_indicator == "A" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_whole_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Previous Settlement Negative Ten Pair
  if previous_settlement_fraction_indicator == "B" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_ten_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Previous Settlement Negative Hundred Pair
  if previous_settlement_fraction_indicator == "C" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_hundred_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Previous Settlement Negative Thousand Pair
  if previous_settlement_fraction_indicator == "D" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Previous Settlement Negative Ten Thousand Pair
  if previous_settlement_fraction_indicator == "E" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_ten_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Previous Settlement Negative Hundred Thousand Pair
  if previous_settlement_fraction_indicator == "F" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_hundred_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Previous Settlement Negative Million Pair
  if previous_settlement_fraction_indicator == "G" then
    return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_negative_million_pair.dissect(buffer, offset, packet, parent)
  end

  -- Dissect Previous Settlement Numeric Pair
  return tmx_mx_solamulticast_hsvf_v1_11.previous_settlement_numeric_pair.dissect(buffer, offset, packet, parent)
end

