-- Dissect: Settlement Price Fraction Pair
tmx_mx_solamulticast_hsvf_v1_11.settlement_price_fraction_pair.dissect = function(buffer, offset, packet, parent, settlement_price_fraction_indicator)
  -- Dissect Settlement Price Negative Whole Pair
  if settlement_price_fraction_indicator == "A" then
    return tmx_mx_solamulticast_hsvf_v1_11.settlement_price_negative_whole_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Settlement Price Negative Ten Pair
  if settlement_price_fraction_indicator == "B" then
    return tmx_mx_solamulticast_hsvf_v1_11.settlement_price_negative_ten_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Settlement Price Negative Hundred Pair
  if settlement_price_fraction_indicator == "C" then
    return tmx_mx_solamulticast_hsvf_v1_11.settlement_price_negative_hundred_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Settlement Price Negative Thousand Pair
  if settlement_price_fraction_indicator == "D" then
    return tmx_mx_solamulticast_hsvf_v1_11.settlement_price_negative_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Settlement Price Negative Ten Thousand Pair
  if settlement_price_fraction_indicator == "E" then
    return tmx_mx_solamulticast_hsvf_v1_11.settlement_price_negative_ten_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Settlement Price Negative Hundred Thousand Pair
  if settlement_price_fraction_indicator == "F" then
