-- Bid Price Quote
tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote = {}

-- Dissect: Bid Price Quote
tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote.dissect = function(buffer, offset, packet, parent, bid_price_quote_opening, bid_price_fraction_indicator, bid_price_fraction_indicator)
  -- Dissect Bid Price Quote Opening Pair
  if bid_price_quote_opening == "OUV" and bid_price_fraction_indicator == "0" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_opening_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Whole Pair
  if bid_price_fraction_indicator == "A" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_whole_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Ten Pair
  if bid_price_fraction_indicator == "B" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_ten_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Hundred Pair
  if bid_price_fraction_indicator == "C" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_hundred_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Thousand Pair
  if bid_price_fraction_indicator == "D" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Ten Thousand Pair
  if bid_price_fraction_indicator == "E" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_ten_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Hundred Thousand Pair
  if bid_price_fraction_indicator == "F" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_hundred_thousand_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bid Price Quote Numeric Negative Million Pair
  if bid_price_fraction_indicator == "G" then
    return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_negative_million_pair.dissect(buffer, offset, packet, parent)
  end

  -- Dissect Bid Price Quote Numeric Pair
  return tmx_mx_solamulticast_hsvf_v1_11.bid_price_quote_numeric_pair.dissect(buffer, offset, packet, parent)
end

