  -- Dissect Group Status Strategies Message
  if message_type == "GS" then
    return tmx_mx_solamulticast_hsvf_v1_11.group_status_strategies_message.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Bulletins Message
  if message_type == "L" then
    return tmx_mx_solamulticast_hsvf_v1_11.bulletins_message.dissect(buffer, offset, packet, parent)
  end
  -- Dissect End Of Sales Message
  if message_type == "S" then
    return tmx_mx_solamulticast_hsvf_v1_11.end_of_sales_message.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Tick Table Message
  if message_type == "TT" then
    return tmx_mx_solamulticast_hsvf_v1_11.tick_table_message.dissect(buffer, offset, packet, parent)
  end
  -- Dissect End Of Transmission Message
  if message_type == "U" then
    return tmx_mx_solamulticast_hsvf_v1_11.end_of_transmission_message.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Circuit Assurance Message
  if message_type == "V" then
    return tmx_mx_solamulticast_hsvf_v1_11.circuit_assurance_message.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Timebeat Message
  if message_type == "Z" then
    return tmx_mx_solamulticast_hsvf_v1_11.timebeat_message.dissect(buffer, offset, packet, parent)
  end

  return offset
end

-- Message Header
tmx_mx_solamulticast_hsvf_v1_11.message_header = {}

-- Size: Message Header
tmx_mx_solamulticast_hsvf_v1_11.message_header.size =
  tmx_mx_solamulticast_hsvf_v1_11.sequence_number.size + 
  tmx_mx_solamulticast_hsvf_v1_11.message_type.size

-- Display: Message Header
tmx_mx_solamulticast_hsvf_v1_11.message_header.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Message Header
tmx_mx_solamulticast_hsvf_v1_11.message_header.fields = function(buffer, offset, packet, parent)
  local index = offset

  -- Sequence Number: N
  index, sequence_number = tmx_mx_solamulticast_hsvf_v1_11.sequence_number.dissect(buffer, index, packet, parent)

  -- Message Type: X
  index, message_type = tmx_mx_solamulticast_hsvf_v1_11.message_type.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Message Header
tmx_mx_solamulticast_hsvf_v1_11.message_header.dissect = function(buffer, offset, packet, parent)
  if show.headers then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_tmx_mx_solamulticast_hsvf_v1_11.fields.message_header, buffer(offset, 0))
    local index = tmx_mx_solamulticast_hsvf_v1_11.message_header.fields(buffer, offset, packet, parent)
    local length = index - offset
    parent:set_len(length)
    local display = tmx_mx_solamulticast_hsvf_v1_11.message_header.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return tmx_mx_solamulticast_hsvf_v1_11.message_header.fields(buffer, offset, packet, parent)
  end
end

-- Packet
tmx_mx_solamulticast_hsvf_v1_11.packet = {}

-- Verify required size of Udp packet
tmx_mx_solamulticast_hsvf_v1_11.packet.requiredsize = function(buffer)
  return buffer:len() >= tmx_mx_solamulticast_hsvf_v1_11.hsvf_stx.size + tmx_mx_solamulticast_hsvf_v1_11.message_header.size
end

-- Dissect Packet
tmx_mx_solamulticast_hsvf_v1_11.packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Dependency for Packet
  local end_of_payload = buffer:len()

  while index < end_of_payload do

    -- Hsvf Stx: character
    index, hsvf_stx = tmx_mx_solamulticast_hsvf_v1_11.hsvf_stx.dissect(buffer, index, packet, parent)

    -- Message Header: Struct of 2 fields
    index, message_header = tmx_mx_solamulticast_hsvf_v1_11.message_header.dissect(buffer, index, packet, parent)

    -- Dependency element: Message Type
    local message_type = trim_right_spaces(buffer(index - 2, 2):string())

    -- Message Body: Runtime Type with 59 branches
    index = tmx_mx_solamulticast_hsvf_v1_11.message_body.dissect(buffer, index, packet, parent, message_type)

    -- Hsvf Etx: character
    index, hsvf_etx = tmx_mx_solamulticast_hsvf_v1_11.hsvf_etx.dissect(buffer, index, packet, parent)
  end

  return index
end


-----------------------------------------------------------------------
-- Protocol Dissector and Components
-----------------------------------------------------------------------

-- Initialize Dissector
function omi_tmx_mx_solamulticast_hsvf_v1_11.init()
end

-- Dissector for Tmx Mx SolaMulticast Hsvf 1.11
function omi_tmx_mx_solamulticast_hsvf_v1_11.dissector(buffer, packet, parent)
  -- Set protocol name
  packet.cols.protocol = omi_tmx_mx_solamulticast_hsvf_v1_11.name

  -- Dissect protocol
  local protocol = parent:add(omi_tmx_mx_solamulticast_hsvf_v1_11, buffer(), omi_tmx_mx_solamulticast_hsvf_v1_11.description, "("..buffer:len().." Bytes)")
  return tmx_mx_solamulticast_hsvf_v1_11.packet.dissect(buffer, packet, protocol)
end


-----------------------------------------------------------------------
-- Protocol Heuristics
-----------------------------------------------------------------------

-- Verify Hsvf Stx Field
tmx_mx_solamulticast_hsvf_v1_11.hsvf_stx.verify = function(buffer)
  -- Attempt to read field
  local value = buffer(0, 1):int()

  if value == 2 then
    return true
  end

  return false
end

-- Dissector Heuristic for Tmx Mx SolaMulticast Hsvf 1.11 (Udp)
local function omi_tmx_mx_solamulticast_hsvf_v1_11_udp_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not tmx_mx_solamulticast_hsvf_v1_11.packet.requiredsize(buffer) then return false end

  -- Verify Hsvf Stx
  if not tmx_mx_solamulticast_hsvf_v1_11.hsvf_stx.verify(buffer) then return false end

  -- Protocol is valid, set conversation and dissect this packet
  packet.conversation = omi_tmx_mx_solamulticast_hsvf_v1_11
  omi_tmx_mx_solamulticast_hsvf_v1_11.dissector(buffer, packet, parent)

  return true
end

-- Register Heuristic for Tmx Mx SolaMulticast Hsvf 1.11
omi_tmx_mx_solamulticast_hsvf_v1_11:register_heuristic("udp", omi_tmx_mx_solamulticast_hsvf_v1_11_udp_heuristic)

-- Register Tmx Mx SolaMulticast Hsvf 1.11 for Decode As
local udp_table = DissectorTable.get("udp.port")
udp_table:add_for_decode_as(omi_tmx_mx_solamulticast_hsvf_v1_11)

